package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.ruoyi.medical.contracts.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class TaskProfessionalPromptCompilerTest {
 final JsonMapper json=new JsonMapper();
 JsonNode prompt(){return json.createObjectNode().put("schema_version","1.0.0").put("node_kind","N02").put("system_instructions","Quote exact authorized evidence. No missing facts may be invented.").put("input_encoding","TASK_NODE_INPUT_CANONICAL_JSON");}
 @Test void literalInstructionsAndRegisteredInputUseDeterministicClosedProjection()throws Exception{var input=json.createObjectNode().put("node_kind","N02").put("question_text","Literal ${notInterpolation}").put("number",Long.MAX_VALUE);var actual=TaskProfessionalPromptCompiler.compileDocument(prompt(),input);assertEquals(prompt().required("system_instructions"),actual.required("instructions"));assertEquals(input,actual.required("task_node_input"));assertEquals(Long.MAX_VALUE,actual.required("task_node_input").required("number").longValue());assertEquals(4,actual.size());}
 @Test void unknownPackageFieldsCannotInjectSystemOrHistory(){var p=(com.fasterxml.jackson.databind.node.ObjectNode)prompt();p.putArray("history");assertThrows(TenantAccessException.class,()->TaskProfessionalPromptCompiler.validatePrompt(p));}
 @Test void wrongNodeAndEncodingNeverReuseAnotherNodePrompt(){var p=(com.fasterxml.jackson.databind.node.ObjectNode)prompt();p.put("node_kind","N05");assertThrows(TenantAccessException.class,()->TaskProfessionalPromptCompiler.validatePrompt(p));p.put("node_kind","N02").put("input_encoding","RAW_HOST_TEXT");assertThrows(TenantAccessException.class,()->TaskProfessionalPromptCompiler.validatePrompt(p));}
 @Test void whitespaceInstructionsAndOversizedUtf8Denied(){var p=(com.fasterxml.jackson.databind.node.ObjectNode)prompt();p.put("system_instructions","   ");assertThrows(TenantAccessException.class,()->TaskProfessionalPromptCompiler.validatePrompt(p));p.put("system_instructions","界".repeat(100000));assertThrows(TenantAccessException.class,()->TaskProfessionalPromptCompiler.validatePrompt(p));}
 JsonNode artifact(int n){return json.createObjectNode().put("artifact_id",String.format("10000000-0000-4000-8000-%012d",n)).put("sha256","a".repeat(64)).put("size_bytes","20").put("media_type","application/json");}
 JsonNode role(){var r=json.createObjectNode().put("schema_version","1.0.0").put("node_kind","N02").put("role_name","Researcher");r.putObject("prompt_basis").put("version_id","10000000-0000-4000-8000-000000000001").put("content_sha256","b".repeat(64));r.set("profile_artifact",artifact(2));return r;}
 JsonNode profile(){var r=json.createObjectNode().put("schema_version","1.0.0").put("node_kind","N02").put("profile_name","medical-agent").put("projection","TEXT_SYSTEM_USER_V1").put("system_prefix","Reviewed SDK prefix");r.set("adapter_artifact",artifact(3));var files=r.putArray("files");for(String p:java.util.List.of("profiles/medical-agent/package.json","profiles/medical-agent/cordis.patch.yml"))files.addObject().put("relative",p).put("sha256","a".repeat(64)).put("size_bytes","20");return r;}
 JsonNode deployment(){var d=json.createObjectNode().put("role_name","Researcher");d.set("profile_artifact",artifact(2));d.set("profile_files",profile().required("files").deepCopy());return d;}
 JsonNode runtime(){var r=json.createObjectNode();r.putArray("event_adapters").addObject().put("component","C07").set("implementation",artifact(3));return r;}
 @Test void wholeProfileSetAndActualPublishedAdapterRequired(){assertDoesNotThrow(()->TaskProfessionalPromptCompiler.requireDeployment(role(),profile(),deployment(),runtime()));var d=(com.fasterxml.jackson.databind.node.ObjectNode)deployment();((com.fasterxml.jackson.databind.node.ArrayNode)d.required("profile_files")).remove(1);assertThrows(TenantAccessException.class,()->TaskProfessionalPromptCompiler.requireDeployment(role(),profile(),d,runtime()));}
 @Test void callerSelectedAdapterOrPathTraversalCannotBecomeReviewedProfile(){var p=(com.fasterxml.jackson.databind.node.ObjectNode)profile();p.set("adapter_artifact",artifact(4));assertThrows(TenantAccessException.class,()->TaskProfessionalPromptCompiler.requireDeployment(role(),p,deployment(),runtime()));((com.fasterxml.jackson.databind.node.ObjectNode)p.required("files").get(0)).put("relative","profiles/../escape");assertThrows(TenantAccessException.class,()->TaskProfessionalPromptCompiler.validateProfile(p));}
 @Test void compiledPromptCapabilityHasNoPublicConstructor(){assertEquals(0,TaskProfessionalPromptCompiler.CompiledPrompt.class.getConstructors().length);}
}
